                            const filterProc = new Gordic.Data.FilterProcessor((meta) => {
                                return ixsSop.length > 0 ? ixsSop.includes(meta.data.ixs_sop) : meta.data.ixs_sop === "XX";
                            });
                            const view = new Gordic.Data.View(rozpocet, { key: "ixs_sop,rok,ixs_hci_ocsp,ixs_esu", processors: { filterProc } });
                            content.gridRozpocet.ggrid("setData", view);
