                            rozpocet.filter((d) => (ixsSop.length > 0 ? ixsSop.includes(d.ixs_sop) : d.ixs_sop === "XX"));
                            const view = new Gordic.Data.View(rozpocet, { key: "ixs_sop,rok,ixs_hci_ocsp,ixs_esu", processors: { filterProc } });
                            content.gridNaroky.ggrid("setData", view);
