                    //#endregion Vynětí
                    //#region PPV
                    const guidPPV = Gordic.Utils.generateGuid();
                    content.beginOperation({ id: guidPPV, text: "jres:34900285" }); //RC 34900285 : Načítám PPV osoby
                    content.isl.OsoPPV.listPPV({ filters: { ixs_esu: content.OsobaFKSPDto.ixs_esu } })
