                    //#endregion Částky soc. programu
                    //#region Hlavička
                    content.findForms("formHlavicka").findFields().gfield("disable");
                    content.findFields().gfield("model", "apply", content.OsobaFKSPDto);
                    const roky = content.OsobaFKSPDto.roky_vyroci ?? 0;
                    const vyroci = content.OsobaFKSPDto.dat_vyroci == null
                        ? ""
                        : "Délka poměru k " +
                            parseDate(content.OsobaFKSPDto.dat_vyroci).toLocaleDateString("cs") +
                            " je " +
                            roky +
                            (roky === 1 ? " rok" : roky > 1 && roky < 5 ? " roky" : " let");
                    content.findFields("pracVyroci").gfield("setInitial", vyroci);
