                    const content = this;
                    const def = $.Deferred();
                    //kontroluje hodnoty oproti nastavení, ale nejsou to chyby
                    if (content.findForms("form").gform("isValid")) {
                        const def_castka = $.Deferred();
                        const castkaVal = content.findFields("c_plan").gfield("getValue");
                        if (content.ProgramDto.omez_uvaz > 0 && (castkaVal == null || castkaVal.eq(0))) {
                            content.dialogs
                                .confirm("jres:29120548", "jres:34900308")
                                .on("no", () => {
                                def.resolve(false);
                            })
                                .on("yes", () => {
                                def_castka.resolve();
                            });
                        }
                        else
                            def_castka.resolve();
                        def_castka.then(() => {
                            if (!content.isNewDto && castkaVal.lessThan(content.RozpocetDto.c_cerpano ?? 0)) {
                                content.dialogs
                                    .confirm("jres:29120548", "jres:34900309".format(parseDecimal(content.RozpocetDto.c_cerpano ?? 0).toString()))
                                    .on("no", () => {
                                    def.resolve(false);
                                })
                                    .on("yes", () => {
                                    def.resolve(true);
                                });
                            }
                            else
                                def.resolve(true);
                        });
                    }
                    else
                        def.resolve(true);
                    return def.promise();
