                        content.VynetiDtos.filter(d => d.ixs_ppv === ixs_ppv && !pidyDrvn.includes(d.ixs_hci_drvn!) && parseDate(d.dat_od!).setHours(0, 0, 0, 0) <= datumDo.getTime() && parseDate(d.dat_do!).setHours(0, 0, 0, 0) >= datumOd.getTime());
        
                    //odpracované měsíce
