                        const uvazek = content.ProgramDto.omez_uvaz ?? 0 > 0 ? WebClient.zjistiUvazek(datOd, content.aktPpvOso.ixs_ppv ?? "", content.ZmenyPPVDtos) : new Decimal(1);
