                                    Content.actions.act_DetailDavky?.enabled(Content.zorbBtn != null && Content.zorbBtn.davky_enabled);
                                    Content.actions.act_Edit?.enabled(Content.zorbBtn != null && Content.zorbBtn.edit_enabled);
