var Gordic;
(function (Gordic) {
    var Per;
    (function (Per) {
        var WebClient;
        (function (WebClient) {
            var gcontent = Decorators.gcontent;
            let GInfoPanel = class GInfoPanel extends Gordic.GContentBase {
                onContentReady() {
                    const that = this;
                    function GetIxsEsuAkt() {
                        if (that.idTab != null) {
                            let dtoDetail = $("#" + "grid_" + that.idTab + "").ggrid("getSelection")[0];
                            if (dtoDetail != null && dtoDetail != undefined) {
                                return dtoDetail.ixs_esu;
                            }
                        }
                        return "";
                    }
                    Gordic.Pam.Breadcrumbs(that, that.title ?? "jres:29120028"); //RC 29120028 : Informační panel
                    that.actions.add({
                        name: "act_Load",
                        caption: "jres:29121041", //RC 29121041 : Občerstvit
                        tooltip: "jres:29121041", //RC 29121041 : Občerstvit
                        captionVisible: "never",
                        icon: "gi-refresh",
                        run: () => {
                            that.descPanel.forEach((detail) => {
                                that.beginOperation();
                                that.call("Seznam", { pageId: detail.list_name })
                                    .done((result) => {
                                    let view = new Gordic.Data.View(result.data_list.list_data, { key: detail.list_pk_fields?.join(',') });
                                    $("#" + "grid_" + detail.list_name).ggrid("setData", view);
                                    if (that.idTab != null && that.idTab === detail.list_name) {
                                        if (view.getCount() === 0) {
                                            that.actions.act_Detail.update({ enabled: false });
                                            that.actions.act_Tisk.update({ enabled: false });
                                        }
                                        else {
                                            that.actions.act_Detail.update({ enabled: true });
                                            that.actions.act_Tisk.update({ enabled: true });
                                        }
                                    }
                                })
                                    .fail(function (result) {
                                    debugger;
                                })
                                    .always(() => {
                                    that.endOperation();
                                });
                                //});
                            });
                        }
                    });
                    that.actions.add({
                        name: "act_Detail",
                        caption: "jres:29120175", //RC 29120175 : Detail osoby
                        enabled: false,
                        tooltip: /*that.dataListDescription.data_right?.ReadReason ??*/ "jres:29120176", //RC 29120176 : Zobrazí detail vybraného zaměstnance
                        icon: "gi-detail", //"gi-detail |gi-user gi-bgw gi-stack-pos--rb",
                        run: () => {
                            const ixsEsu = GetIxsEsuAkt();
                            if (ixsEsu != "") {
                                that.navigate(["Gordic.Per.WebClient.GDetailOsoby", {
                                    //gridRemoteControl: new Gordic.Components.GridRC(this.grid)
                                    }], {
                                    taskId: that.taskId,
                                    uid: "OsoInfoPanelDetail#",
                                    //Action: EnumActions.Detail,
                                    Ixsesu: ixsEsu,
                                    isEditable: true,
                                }).on("close", (ev, obj) => {
                                    //debugger;
                                    if (obj == null || obj === true) {
                                        debugger;
                                        that.actions.act_Load.run();
                                    }
                                });
                            }
                        }
                    });
                    that.actions.add(GAction.createPrintAction({
                        name: "act_Tisk",
                        caption: "jres:29120047", //RC 29120047 : Tisk
                        tooltip: "jres:29120047", //RC 29120047 : Tisk
                        icon: "fa-print",
                        tema: "per_ptm_osoby",
                        schedulingDisabled: true,
                        parentContent: this,
                        fullScreen: false, //true,
                        keepOpen: false, //true,
                        enabled: false,
                        favorite: true,
                        serverParameterMethod: "Gordic.Per.WebClient.GInfoPanel:ParametrySestavy",
                        serverRestrictionAlvMethod: "Gordic.Per.WebClient.GInfoPanel:RestrictionAlv",
                        reportStarting: function (rep) {
                            rep.customDto = { char_1: GetIxsEsuAkt() };
                        },
                    }));
                    that.menuBar(this.actions.createBar(this.normalBar, ["act_Load*"]));
                    const groups = [];
                    that.divGrids = $("<div id='grids'>").appendTo(that.element);
                    that.descPanel.forEach((detail) => {
                        groups.push({
                            id: detail.list_name ?? "",
                            caption: detail.list_caption ?? ""
                        });
                        const tabGrid = $("<div>").appendTo(that.divGrids)
                            .ggroupable({
                            group: { id: detail.list_name ?? "" },
                            conceal: (ev, ctx) => {
                                tabGrid.toggle(!ctx.conceal);
                            }
                        });
                        $("<div id='grid_" + detail.list_name + "'>")
                            .appendTo(tabGrid)
                            .gautofit()
                            .ggrid({
                            name: "ggrid_" + detail.list_name,
                            data: [],
                            renderMode: "auto",
                            columnMode: "full",
                            navigationMode: "row",
                            columns: Per.WebControls.createGridFormat(detail),
                            defaultProfile: {
                                columnList: Per.WebControls.createColumnListString(detail),
                                sort: Per.WebControls.createSortString(detail)
                            },
                            defaultAction: that.actions.act_Detail
                        });
                    });
                    that.tabmanager = $("<div id='tabmanager'>").gtabmanager({
                        groups: groups,
                        displayLevel: 1,
                        scopeElement: that.divGrids,
                        open: (ev, ctx) => {
                            that.idTab = ctx?.id;
                            if ($("#" + "grid_" + that.idTab + "").ggrid("getView").getCount() === 0) {
                                that.actions.act_Detail.update({ enabled: false });
                                that.actions.act_Tisk.update({ enabled: false });
                            }
                            else {
                                that.actions.act_Detail.update({ enabled: true });
                                that.actions.act_Tisk.update({ enabled: true });
                            }
                            //that.actions.act_Load?.run();
                        }
                    });
                    that.divGrids.before(that.tabmanager);
                    if (that.descPanel.length > 0) {
                        that.idTab = groups[0].id;
                        that.tabmanager.gtabmanager("setActive", groups[0]);
                        that.actions.act_Load.run();
                    }
                    that.tabmanager.gtabmanager("visibleGroup", "_tabGroupOthers", false); //vypnutí listu přidaného navic (proč tam vůbec je?)
                }
            };
            GInfoPanel = __decorate([
                gcontent
            ], GInfoPanel);
            WebClient.GInfoPanel = GInfoPanel;
        })(WebClient = Per.WebClient || (Per.WebClient = {}));
    })(Per = Gordic.Per || (Gordic.Per = {}));
})(Gordic || (Gordic = {}));
