                    content.actions.act_Print?.visible(!content.JeBIS);
                    content.actions.act_Print?.enabled(!content.isNew);
                    content.actions.act_Cancel?.visible(content.Ukladat && !content.isNew);
                    content.actions.act_Cancel?.enabled(content.Ukladat && !content.isNew && !readOnly);
                    content.actions.act_Documents?.visible(!content.isNew && content.ParametrPerPropoOpatreniDok);
                    content.actions.act_Documents?.enabled(!content.isNew && content.ParametrPerPropoOpatreniDok);
                    content.actions.act_Changes?.visible(!content.isNew && content.ParametrPerSlZmen === Per.WebControls.UrovenSledovaniZmen.ano_opatreni);
