                    drpo.gfield("option", "disabled", !content.EditDrpo || readOnlyFrm);
                    content.findFields("ixs_hci_dupo").gfield("option", "disabled", !drpo.gfield("hasValue") || readOnlyFrm);
                    content.findFields("popis").gfield("option", "disabled", readOnlyFrm || content.JeBIS);
