                        return;
                    const guid = Gordic.Utils.generateGuid();
                    content.beginOperation({ id: guid, text: "jres:34900166" }); //RC 34900166 : Načítám personální opatření
                    content.isl.OpatreniService.list({ filters: { ixs_esu: content.OpatreniDto.ixs_esu, aktivni: true, zjistitVazbu: false } })
                        .getData()
                        .then((opatreni) => {
                        if (opatreni.length > 0) {
                            new Gordic.Data.Selectors.DefaultSelector({
                                related: content.element,
                                title: "jres:34900163", //RC 34900163 : Personální opatření
                                canSelectEmpty: true,
                                data: opatreni,
                                multi: false,
                                gridFormat: content.getGridFormatPO(),
                                gridOpts: {
                                    columnMode: "fit",
                                    showTopPanel: false,
                                    showHeaderRow: true,
                                    showBottomPanel: true,
                                    defaultProfile: {
                                        sort: "!dat_od",
                                    },
                                },
                            })
                                .show()
                                .done((selDto) => {
                                if (selDto != null) {
                                    if (content.OpatreniDto.poradi != selDto.poradi) {
                                        content.OpatreniDto.poradi = selDto.poradi;
                                        content.poradiOpatreni = selDto.poradi;
                                        content.bylaZmenaPO = true;
                                        content.updateSaveButton();
                                    }
                                }
                                else {
                                    content.findFields("typEditace").gfield("setValue", Per.WebControls.DruhEditPO.nova);
                                    content.OpatreniDto.poradi = null;
                                    content.poradiOpatreni = -1; //null
                                    content.findFields().gfield("model", "apply", content.OpatreniDto);
                                }
                            });
                        }
                    })
                        .always(() => {
                        content.endOperation(guid);
                    });
