                getFormBuilderDetail() {
                    const that = this;
                    const fb = new Gordic.Forms.Form({ name: "form", layoutDescriptor: "L2M2S1" });
                    fb.addSection()
                        .addRow({ label: "Platnost od/do", required: true })
                        .addField("gdatebox", "w-6", { name: "dat_od", validators: [new Gordic.Validators.Required()], placeholder: "Platnost od" })
                        .addField("gdatebox", "w-6", { name: "dat_do", validators: [new Gordic.Validators.Required()], placeholder: "Platnost do" })
                        .addRow({ label: "Podíl na úvazku", required: true })
                        .addField("gnumberbox", {
                        name: "uvazek",
                        validators: [new Gordic.Validators.Required(), new Gordic.Validators.Range({ min: 0, max: 1 })],
                        decimals: 4,
                        returnType: "decimal",
                    })
                        .addRow({ label: "Nadřízený organizační celek" })
                        .addField("gselectbox", Gordic.Prefabs.Select.gCisReaderOCENad(), {
                        name: "ixs_oce_nad",
                        disabled: true,
                        model: "model.ixs_oce_pod=value.ixs_oce_pod",
                    })
                        .addRow({ label: "Organizační celek" })
                        .addField("gselectbox", Gordic.Prefabs.Select.gCisReaderOCE(false, true), {
                        name: "ixs_oce",
                        model: "model.ixs_oce=value.ixs_oce,model.oce_nazev=value.nazev_oce,model.oce_id=value.id_oce",
                        //serverFilters: {
                        //    aktivita: 100,
                        //},
                        change: (ev, obj) => {
                            const cnt = $.content(ev.target);
                            if (obj.value) {
                                cnt.findFields("ixs_oce_nad").gfield("model", "apply", { ixs_oce_pod: obj.value.ixs_oce });
                            }
                            else {
                                cnt.findFields("ixs_oce_nad").gfield("clear");
                            }
                        },
                        //selectorFormat: new Gordic.Data.GridFormat()
                        //    .addTextColumn({ name: "id_oce", caption: "ID OCE" })
                        //    .addTextColumn({ name: "nazev_oce", caption: "Název OCE" })
                        //    .addTextColumn({ name: "zkratka_oce", caption: "Zkratka OCE" })
                        //    .addTextColumn({ name: "dat_od_oce", caption: "Od" })
                        //    .addTextColumn({ name: "dat_do_oce", caption: "Do" }),
                    })
                        .addRow({ label: "Zařazení na SYM" })
                        .addField("gselectbox", that.JeISTA
                        ? Gordic.Prefabs.Select.gCisReaderZarazeniNaSM(that.JeBIS, true, that.JeSluzba, true)
                        : Gordic.Prefabs.Select.gCisReaderZarazeniNaSM(false, false, false, true), {
                        name: "ixs_sym",
                        model: "model.ixs_sym=value.ixs_sym,model.ixs_sym_txt<=value.nazev_sm,model.ixs_sym_id<=value.id_sm," +
                            "model.dat_od_sm=<value.dat_od_sm,model.dat_do_sm<=value.dat_do_sm,model.oce_cesta<=value.oce_cesta",
                        serverFilters: {
                            ixs_oce: new Gordic.Forms.Dependency("ixs_oce", "ixs_oce", false, true),
                            neomezovat_zar: true,
                        },
                        //change: (ev, changeObj) => {
                        //    const cnt = $.content(ev.target);
                        //    if (changeObj.value != null) {
                        //        //this.findFields("ixs_oce").gfield("setValue", { ixs_oce: changeObj.value.ixs_oce });
                        //        cnt.findFields("ixs_oce").gfield("model", "apply", { ixs_oce: changeObj.value.ixs_oce });
                        //        //this.findFields("ixs_oce_nad").gfield("setValue", { ixs_oce_pod: changeObj.value.ixs_oce });
                        //        cnt.findFields("ixs_oce_nad").gfield("model", "apply", { ixs_oce_pod: changeObj.value.ixs_oce });
                        //    }
                        //},
                        selectorFormat: new Gordic.Data.GridFormat()
                            .addTextColumn({ name: "id_oce", caption: "ID OCE" })
                            .addTextColumn({ name: "nazev_oce", caption: "Název OCE" })
                            .addTextColumn({ name: "id_sm", caption: "ID SYM" })
                            .addTextColumn({ name: "nazev_sm", caption: "Název SYM" })
                            .addTextColumn({ name: "nazev_zar", caption: "Zařazená osoba" })
                            .addDateColumn({ name: "dat_od_sm", caption: "SYM od" })
                            .addDateColumn({ name: "dat_do_sm", caption: "SYM do" })
                            .addDateColumn({ name: "dat_od_zar", caption: "Zař. od" })
                            .addDateColumn({ name: "dat_do_zar", caption: "Zař. do" })
                            .addTextColumn({ name: "oce_cesta", caption: "Umístění" }),
                    })
                        .addRow({ label: "Poznámka" })
                        .addField("gstringbox", { name: "poznamka" })
                        .addRow()
                        .addField("gcheck", {
                        name: "pov_zast",
                        label: "Osoba (PPV) pověřena zastupováním",
                        modelValueTransform: {
                            apply: function (modelValue) {
                                return modelValue === 1;
                            },
                            collect: function (fieldValue) {
                                return fieldValue === true ? 1 : 0;
                            },
                        },
                    });
                    if (that.JeStatZam || that.JePracPomerISoSS) {
                        fb.addRow({ label: "Převedení/přeložení", required: true }).addField("gselectbox", Gordic.Prefabs.Select.gCisReaderCasCiselnik(), {
                            name: "ixs_hci_pjsm",
                            model: "model.ixs_hci_pjsm=value.ixs_hci",
                            serverFilters: { ciselnik_sloupec: "ixs_hci_pjsm" },
                            validators: [new Gordic.Validators.Required()],
                        });
                    }
                    return fb;
                }
                showDialog(dotaz) {
                    const def = $.Deferred();
                    const that = this;
                    //let dotaz: string = "jres:29122646".format(ixs_symA, ixs_symB, dat1, dat2); //RC 29122646 : Konec zařazení na SYM '{0}' se překrývá se zařazením na SYM '{1}'. Chcete konec zařazení upravit z {2} na {3}?
                    that.dialogs.messageBox("Informace", dotaz, GDlg.mbbYesNoCancel, GDlg.mbiQuestion, 400, 190).on("close", (ev, o, args) => {
                        if (o === "yes") {
                            def.resolve(true);
                        }
                        else if (o === "cancel") {
                            def.resolve(null);
                        }
                        else if (o === "no") {
                            def.resolve(false);
                        }
                    });
                    return def.promise();
                }
