                                        return -1;
                                    if (parseDate(a.dat_od) < parseDate(b.dat_od))
                                        return 1;
                                    // Pokud stejné datum, seřadit podle poradi sestupně
                                    if (a.poradi > b.poradi)
                                        return -1;
                                    if (a.poradi < b.poradi)
                                        return 1;
                                    return 0;
