                /// <summary>Určí maximální povolený rozsah počtu hodin DPČ</summary>
                nastavRozsahDPC() {
                    const that = this;
                    const druhPpvIxsHci = that.findFields("ixs_hci_drpp").gfield("getValue")?.ixs_hci;
                    const datOd = that.findFields("PPV_od").gfield("getValue");
                    const datDo = that.findFields("PPV_do").gfield("getValue");
                    if (!that.JeBIS &&
                        druhPpvIxsHci != null &&
                        druhPpvIxsHci == "0000BHR0077X" &&
                        datOd != null &&
                        parseDate(datOd).getFullYear() >= 1950 &&
                        parseDate(datOd).getFullYear() < 2999 &&
                        datDo != null &&
                        parseDate(datDo).getFullYear() >= 1950 &&
                        parseDate(datDo).getFullYear() < 2999) {
                        const guid = Gordic.Utils.generateGuid();
                        that.beginOperation({ id: guid });
                        that.isl.OsoPPV.maxRozsahDPC({ dat_od: datOd, dat_do: datDo })
                            .get()
                            .then((rozsah) => {
                            that.findFields("rozsah").gfield("setValue", rozsah);
                        })
                            .catch((err) => {
                            if (err.errorType === "info") {
                                //"info" = C# GNonFatalException
                                Per.WebControls.showError(that, "Maximální povolený rozsah počtu hodin DPČ", (err.title ? err.title + " - " : "") + err.message);
                            }
                            else
                                throw err;
                        })
                            .always(() => that.endOperation(guid));
                    }
                }
                //počet změn data do u konkrétního PPV
                pocetZmenDatDoPPV() {
                    const that = this;
                    if (that.dtoZmenyPPVList == null)
                        return 0;
                    let pocetZmen = 0;
                    let datumPred = Per.WebControls.dateMinValue();
                    //datum, který se bude kontrolovat
                    const datumDoAkt = that.findFields("PPV_do").gfield("getValue") ?? Per.WebControls.dateMinValue();
                    let jeDatumDo = false;
                    const dtos = that.dtoZmenyPPVList.filter((d) => d.aktivita === 100).sort((a, b) => parseDate(a.ppv_do).getTime() - parseDate(b.ppv_do).getTime());
                    dtos.forEach((dto) => {
                        if (datumPred.getTime() === Per.WebControls.dateMinValue().getTime() || datumPred < parseDate(dto.ppv_do)) {
                            datumPred = parseDate(dto.ppv_do);
                            if (!jeDatumDo && datumDoAkt.getTime() == datumPred.getTime()) {
                                jeDatumDo = true;
                            }
                            if (datumPred.getTime() !== Per.WebControls.dateMaxValue().getTime()) {
                                //nesmí byt na dobu neurčitou
                                pocetZmen += 1;
                            }
                        }
                    });
                    if (!jeDatumDo) {
                        pocetZmen += 1; //přičtu ještě aktuální změnu
                    }
                    return pocetZmen;
                }
