                nastavDetailSYMDto() {
                    const that = this;
                    let ixsSym = null;
                    //více zařazení na SYM pro jedno PPV
                    if (that.ParametrPerRadVicZar) {
                        if (that.dtoPracovniZarazeniList != null && that.dtoPracovniZarazeniList.length > 0) {
                            let datum;
                            if (that.Action === Per.WebControls.EnumActions.New) {
                                const datEvidOd = that.findFields("PPV_od").gfield("getValue");
                                if (!datEvidOd != null) {
                                    if (new Date() > parseDate(datEvidOd)) {
                                        //případ, kdy se zadává PPV zpětně a zařazení je později (není od počátku ppv)
                                        datum = new Date();
                                    }
                                    else {
                                        datum = parseDate(datEvidOd);
                                    }
                                    if (that.dtoPracovniZarazeniList.filter((d) => d.dat_od != null && d.aktivita < 900).length > 0 &&
                                        that.dtoPracovniZarazeniList.filter((d) => d.dat_od != null && parseDate(d.dat_od) <= datum && d.dat_do != null && parseDate(d.dat_do) >= datum && d.aktivita < 900).length == 0) {
                                        //jestliže se to chystá dopředu
                                        datum = parseDate(that.dtoPracovniZarazeniList
                                            .filter((d) => d.dat_od != null && d.aktivita < 900)
                                            .sort((a, b) => parseDate(b.dat_od).getTime() - parseDate(a.dat_od).getTime())[0].dat_od);
                                    }
                                }
                                else {
                                    datum = new Date();
                                }
                            }
                            else {
                                const zmenaOd = that.findFields("dat_plat").gfield("getValue");
                                if (zmenaOd != null) {
                                    datum = parseDate(zmenaOd);
                                }
                                else {
                                    const datEvidDo = that.findFields("PPV_do").gfield("getValue");
                                    if (datEvidDo != null &&
                                        that.dtoDetailPPV.PPV_do != null &&
                                        parseDate(datEvidDo).getTime() != parseDate(that.dtoDetailPPV.PPV_do).getTime()) {
                                        //změna pouze data do
                                        datum = parseDate(datEvidDo);
                                    }
                                    else {
                                        datum = new Date();
                                    }
                                }
                            }
                            //zjistím první aktuální SYM
                            const dtos = that.dtoPracovniZarazeniList
                                .filter((d) => d.dat_od != null &&
                                parseDate(d.dat_od) <= datum &&
                                d.dat_do != null &&
                                parseDate(d.dat_do) >= datum &&
                                d.pov_zast == 0 &&
                                d.aktivita < 900)
                                .sort((a, b) => {
                                const aDate = parseDate(a.dat_od);
                                const bDate = parseDate(b.dat_od);
                                if (aDate > bDate)
                                    return -1;
                                if (aDate < bDate)
                                    return 1;
                                const aPor = a.poradi == null ? Number.MAX_SAFE_INTEGER : a.poradi;
                                const bPor = b.poradi == null ? Number.MAX_SAFE_INTEGER : b.poradi;
                                if (aPor > bPor)
                                    return -1;
                                if (aPor < bPor)
                                    return 1;
                                return 0;
                            });
                            if (dtos.length > 0) {
                                ixsSym = dtos[0].ixs_sym;
                            }
                            else if (that.dtoPracovniZarazeniList.length > 0) {
                                ixsSym = that.dtoPracovniZarazeniList[0].ixs_sym;
                            }
                        }
                    }
                    else {
                        ixsSym = that.findFields("ixs_sym").gfield("getValue")?.ixs_sym;
                    }
                    if (ixsSym != null) {
                        if (that.dtoDetailSM == null || that.dtoDetailSM.ixs_sym != ixsSym) {
                            const guid = Gordic.Utils.generateGuid();
                            that.beginOperation({ id: guid, text: "Načítám detail SM" });
                            that.call("GetDetailSM", { ixs_sym: ixsSym })
                                .then((detail) => {
                                that.dtoDetailSM = detail;
                            })
                                .always(() => that.endOperation(guid));
                        }
                    }
                    else {
                        if (that.dtoDetailSM != null)
                            that.dtoDetailSM = null;
                    }
                }
