                    detailPPV.ixs_ppv = PPV.ixs_ppv;
                    detailPPV.ixs_esu = PPV.ixs_esu;
                    detailPPV.PPV_od = PPV.dat_od; //PPV_do se plní přes ZmenyPPV, důvodem je sledování změn konce PPV
