                    detailPPV.ixs_hci_sloz = zmenyPPV.ixs_hci_sloz;
                    detailPPV.ixs_hci_sloz_txt = zmenyPPV.ixs_hci_sloz_txt;
                    detailPPV.ixs_kvm = zmenyPPV.ixs_kvm;
                    detailPPV.ixs_kvm_txt = zmenyPPV.ixs_kvm_txt;
                    detailPPV.ixs_kvm_kod = zmenyPPV.ixs_kvm_kod;
                    detailPPV.ixs_hci_duvp = zmenyPPV.ixs_hci_duvp;
                    detailPPV.popis_duvp = zmenyPPV.popis_duvp;
                    detailPPV.ixs_hci_duvu = zmenyPPV.ixs_hci_duvu;
                    detailPPV.zpv_pp = zmenyPPV.zpv_pp;
                    detailPPV.ixs_hci_drpp = zmenyPPV.ixs_hci_drpp;
                    detailPPV.priz_zdr_prhl = zmenyPPV.priz_zdr_prhl;
                    detailPPV.dat_nastup = zmenyPPV.dat_nastup;
                    detailPPV.ixs_hci_prdp = zmenyPPV.ixs_hci_prdp;
                    detailPPV.fond_pd = zmenyPPV.fond_pd;
                    detailPPV.prac_fond = zmenyPPV.prac_fond;
                    detailPPV.uvazek = zmenyPPV.uvazek;
                    detailPPV.dat_podpis = zmenyPPV.dat_podpis;
                    detailPPV.dat_podpis_zam = zmenyPPV.dat_podpis_zam;
