                    if (jeNovyPpv || that.jeSchvaleni)
                        that.dtoDetailPPV.aktivita_ppv = that.jeSchvaleni ? 100 : 600;
                    if (zneaktivniNovejsi == null)
                        zneaktivniNovejsi = false;
                    //------
                    //#region Pracovní zařazení na SYM
