                        zmenyZarazeni: listZmenyZarazeni,
                        zmenyZarazeni_po: null, //TODO:
                        zmenyZarazeni_po_uk: null, //TOOD:
                        zarazeni: listZarazeni, //TODO:
                        zarazeni_po: null, //TODO:
                        zarazeni_po_uk: null, //TODO:
                        zamestnani: null, //TODO:
