                                //    foreach(GPraceDataSet.PracovniZarazeniRow radek in PracovniZarazeniTable) {
                                //        if (!radek.dat_od.IsNull /*&& ((m_oPracPomer.JeNovyPPV && radek.ixs_ppv.IsNullOrWhiteSpace) || (!m_oPracPomer.JeNovyPPV && m_oPracPomer.PIDPPV == radek.ixs_ppv))*/) {
                                //            if (radek.dat_od.BaseValue != m_oTbGDatEvidOd.Value.BaseValue) {
                                //                radek.dat_od = m_oTbGDatEvidOd.Value.BaseValue;
                                //                if (!radek.dat_do.IsNull && radek.dat_od > radek.dat_do) {
