                    that.actions.add({
                        name: "act_PlatVymer_Save",
                        caption: "Uložit",
                        icon: "fa-save",
                        tooltip: "Uložit záznam",
                        run: async () => {
                            //políčka ve formu se změnily, mají hodnoty a hodnoty jsou validní, pak můžu ukládat
                            if ( /*this.findFields().gfield("hasChanged") && this.findFields().gfield("hasValue") && */that.findForms("form").gform("isValid")) {
                                const dto = {
                                    ixs_ppv: that.Ixsppv,
                                    stav_zprac: 20, //ukládám jako schválené
                                    aktivita: 100, //ukládám jako schválené
                                    typ_pvv: 10,
                                    priz_vymer: 1,
                                    dat_do: that.dtoPracPomer.dat_do,
                                    priz_vyp_st: 1,
                                };
                                that.findFields().gfield("model", "collect", dto);
                                if (dto.dat_podpis == null) {
                                    //debugger;
                                    dto.dat_podpis = Per.WebControls.DateToJSONFormatstring(new Date());
                                }
                                let konec = false;
                                let zrusitStarsiNeschvalene = null;
                                let zneaktivniNovejsi = null;
                                let ponechatStejDen = null;
                                if (dto.dat_od != null) {
                                    //jeSchvaleni = true momentálně
                                    //řazení dat_od DESC
                                    that.dtoListPlatVymer.sort((a, b) => new Date(b.dat_od.toString()).getTime() - new Date(a.dat_od.toString()).getTime());
                                    for (let i = 0; i < that.dtoListPlatVymer.length; i++) {
                                        const item = that.dtoListPlatVymer[i];
                                        if (zneaktivniNovejsi == null &&
                                            item.aktivita === 100 &&
                                            item.dat_od &&
                                            new Date(item.dat_od.toString()).getTime() > new Date(dto.dat_od.toString()).getTime()) {
                                            await that.showDialog("jres:29120575").done((result) => {
                                                //RC 29120575 : Existují novější platové výměry, které budou zrušeny. Chcete pokračovat?
                                                if (result === true) {
                                                    zneaktivniNovejsi = true;
                                                }
                                                else {
                                                    konec = true;
                                                }
                                            });
                                            /*this.dialogs.confirm("Informace", "Existují novější platové výměry, které budou zrušeny. Chcete pokračovat?")
                                                .on("yes", () => {
                                                    zneaktivniNovejsi = true;
                                                })
                                                .on("no", () => {
                                                    konec = true;
                                                });*/
                                            if (zrusitStarsiNeschvalene != null || konec)
                                                break;
                                        }
                                        else if (item.poradi_plv != dto.poradi_plv &&
                                            new Date(item.dat_od.toString()).getTime() == new Date(dto.dat_od.toString()).getTime()) {
                                            if (that.JeBIS && (item.aktivita == 100 || item.aktivita == 300)) {
                                                const date = new Date(item.dat_od.toString());
                                                const dateStr = date.getDate() + "." + date.getMonth() + "." + date.getFullYear();
                                                await that.showDialog("jres:32730202".format(dateStr)).done((result) => {
                                                    //RC 32730202 : Ve stejný den ({0}) již existuje platový výměr. Chcete ho zrušit?
                                                    if (result === true) {
                                                        ponechatStejDen = true;
                                                    }
                                                });
                                            }
                                            else if (item.aktivita == 100) {
                                                const date = new Date(item.dat_od.toString());
                                                const dateStr = date.getDate() + "." + date.getMonth() + "." + date.getFullYear();
                                                await that
                                                    .showDialog("jres:29120677".format(dateStr)) //RC 29120677 : Ve stejný den ({0}) již existuje schválený platový výměr, který bude přepsán. Chcete pokračovat?
                                                    .done((result) => {
                                                    if (result === false) {
                                                        konec = true;
                                                    }
                                                });
                                                if (konec)
                                                    break;
                                            }
                                            else if (item.aktivita != 900 && zrusitStarsiNeschvalene == null) {
                                                const date = new Date(item.dat_od.toString());
                                                const dateStr = date.getDate() + "." + date.getMonth() + "." + date.getFullYear();
                                                await that
                                                    .showDialog("jres:29120628".format(dateStr)) //RC 29120628 : Ve stejný den ({0}) existují neschválené platové výměry, chcete je zrušit?
                                                    .done((result) => {
                                                    if (result === true) {
                                                        zrusitStarsiNeschvalene = true;
                                                    }
                                                    else {
                                                        konec = true;
                                                    }
                                                });
                                                if (zneaktivniNovejsi != null || konec)
                                                    break;
                                            }
                                        }
                                    }
                                }
                                if (!konec) {
                                    //debugger;
                                    //TODO: plnění do DTO pro ukládání
                                    const save = {
                                        detail: dto,
                                        opatreni: null,
                                        opatreni_ukonceni: null,
                                        zrusitNovejsi: zneaktivniNovejsi == null ? false : zneaktivniNovejsi,
                                        zrusitStarsiNeschvalene: zrusitStarsiNeschvalene == null ? false : zrusitStarsiNeschvalene,
                                        ponechatStejDen: ponechatStejDen == null ? false : ponechatStejDen,
                                        //prepSlozkyDatOd: false,
                                        slozky: that.dtoListPlatVymerSlozky,
                                        //plneni: null //TODO: dotaz na uložení dat o plnění kval. předpokladu při rozdílných datech
                                    };
                                    const guid = "SavePlatVymer";
                                    that.beginOperation({ id: guid, text: "Probíhá uložení platového výměru." });
                                    that.isl.PpvPlatVymer.upsert(save)
                                        .get()
                                        .done(() => {
                                        //that.showFlash("Platový výměr uložen.", "success");
                                        Per.WebControls.showSucess(that, "Uložení platového výměru", "Platový výměr uložen.");
                                        that.jeZmena = true;
                                        that.dtoPlatVymer = {};
                                        that.findFields().gfield("option", "disabled", true);
                                        that.actions.act_PlatVymer_Save.enabled(false); //prohlížím z historie, dokud nechci nový, není co ukládat
                                        that.actions.act_Slozky_Add.enabled(false);
                                        that.actions.act_Slozky_Detail.enabled(false);
                                        that.actions.act_Slozky_Delete.enabled(false);
                                        that.actions.act_PlatVymer_Load.run();
                                    })
                                        .catch((err) => {
                                        if (err.errorType === "info") { //"info" = C# GNonFatalException
                                            Per.WebControls.showError(that, "jres:34900660", (err.title ? err.title + " - " : "") + err.message);
                                        }
                                        else
                                            throw err;
                                    })
                                        .always(() => {
                                        that.endOperation(guid);
                                    });
                                }
                            }
                            return null;
                        },
                        customClass: "g-button--primary",
                    });
