                    const slozka_mzdy = mainContent.findFields("druh_tab").gfield("getValue") != null ? mainContent.findFields("druh_tab").gfield("getValue").slozka_mzdy : null;
                    const slozka_mzdy_txt = mainContent.findFields("druh_tab").gfield("getValue") != null ? mainContent.findFields("druh_tab").gfield("getValue").slozka_mzdy_txt : null;
