                            Gordic.Pam.CallWithPromise("ZjistiCTarif", { druhTab: druh_tab, platTrida: plat_trida, platStupen: plat_stupen, datum: null }, "Gordic.Per.WebClient.GUdajeZamFrmPlatVymer")
