                                    const rows = mainContent.dtoListPlatVymerSlozky.filter((r) => r.slozka_mzdy === slozka_mzdy);
                                    if (rows.length === 0) {
                                        const dto = {
                                            ixs_ppv: mainContent.Ixsppv,
                                            ixs_tks: mainContent.IxsTks,
                                            aktivita: 100,
                                            dat_od_plv: dat_od,
                                            dat_od: dat_od,
                                            dat_do: mainContent.dtoPracPomer.dat_do,
                                            stat: 42,
                                            slozka_mzdy: slozka_mzdy,
                                            slozka_mzdy_txt: slozka_mzdy_txt,
                                            druh: 0,
                                            mena: 0,
                                            mena_txt: "CZK",
                                            proc_saz: new Decimal(1),
                                            c_sazba: new Decimal(0),
                                            uvazek: new Decimal(1),
                                            c: tarif,
                                            c_mena: tarif,
                                            c_uvazek: tarif,
                                            poznamka: "Automaticky generovaná složka.",
                                        };
                                        mainContent.dtoListPlatVymerSlozky.push(dto);
                                    }
                                    else {
                                        const slozkaDto = rows[0];
                                        slozkaDto.c = tarif;
                                        slozkaDto.c_mena = tarif;
                                        slozkaDto.c_uvazek = tarif;
                                    }
                                    mainContent.gridSlozky.ggrid("setData", mainContent.dtoListPlatVymerSlozky);
                                    let celkem = new Decimal(0);
                                    mainContent.dtoListPlatVymerSlozky.forEach((dto) => {
                                        if (dto.c_mena != null)
                                            celkem = celkem.add(dto.c_mena);
                                    });
                                    Per.WebControls.setStatusPanel(mainContent.gridSlozky, "celkem", `Celkem: ${celkem.toString().replace(/\B(?=(\d{3})+(?!\d))/g, " ")} Kč`);
                                    //mainContent
                                    //    .findFields("section: celkem")
